                params={
                    'key': api_key
                }
            )
        if r.status_code == 200:
            result = r.json()
            if 'outputs' in result and len(result['outputs']) > 0:
                ds_id = result['outputs'][0]['id']
                gene_lists[f'{strain}_{direction}'] = ds_id
                print(f'Uploaded {fname}: {ds_id}')
            else:
                print(f'Upload {fname}: unexpected response: {r.text[:200]}')
        else:
            print(f'Upload {fname} failed: {r.status_code} {r.text[:200]}')

print('\nGene list dataset IDs:')
for k, v in gene_lists.items():
    print(f'  {k}: {v}')
