import requests, os

api_key = open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
hist_id = 'bbd44e69cb8906b587ee340204072eed'
headers = {'x-api-key': api_key}

results = {
    '97_up': 'f9cad7b01a472135d84452f965ad02dc',
    '97_down': 'f9cad7b01a4721357b71c72819d783d9',
    '98_up': 'f9cad7b01a4721357e9c33a7eb886623',
    '98_down': 'f9cad7b01a472135dd6bb1bbe520c639',
    '99_up': 'f9cad7b01a472135f822e5ec6eb08e66',
    '99_down': 'f9cad7b01a472135c2466fc5c4245da9',
}

# Parse each result file
def parse_ora_results(ds_id):
    r = requests.get(f'https://usegalaxy.org/api/histories/{hist_id}/contents/{ds_id}/display', headers=headers)
    lines = r.text.strip().split('\n')
    header = lines[0].split('\t')
    data = []
    for line in lines[1:]:
        if not line.strip():
            continue
        fields = line.split('\t')
        row = dict(zip(header, fields))
        data.append(row)
    return header, data

for key, ds_id in results.items():
    header, data = parse_ora_results(ds_id)
    # Get significant pathways (padj < 0.05)
    sig = []
    for row in data:
        try:
            padj = float(row['adjusted_p_value'])
            if padj < 0.05:
                sig.append((row['pathway_id'], row['pathway_name'], padj, row['foreground_hits'], 
                           row['pathway_genes_in_universe'], row['foreground_genes_in_universe']))
        except (ValueError, KeyError):
            pass
    print(f"\n{key}: {len(sig)} significant pathways (padj < 0.05):")
    for pid, pname, padj, fg_hits, pw_genes, fg_uni in sig:
        print(f"  {pid}: {pname} (padj={padj:.2e}, hits={fg_hits}/{pw_genes})")

# Find intersection for UP direction
print("\n\n=== UP DIRECTION INTERSECTION ===")
up_sets = {}
for strain in ['97', '98', '99']:
    key = f'{strain}_up'
    ds_id = results[key]
    header, data = parse_ora_results(ds_id)
    sig = set()
    for row in data:
        try:
            if float(row['adjusted_p_value']) < 0.05:
                sig.add(row['pathway_id'])
        except (ValueError, KeyError):
            pass
    up_sets[strain] = sig
    print(f"{key} significant: {sorted(sig)}")

up_common = up_sets['97'] & up_sets['98'] & up_sets['99']
print(f"\nCommon UP pathways: {sorted(up_common) if up_common else 'NONE'}")

# For the common ones, show details
if up_common:
    for pid in sorted(up_common):
        print(f"\n  {pid}:")
        for strain in ['97', '98', '99']:
            key = f'{strain}_up'
            ds_id = results[key]
            header, data = parse_ora_results(ds_id)
            for row in data:
                if row['pathway_id'] == pid:
                    print(f"    {strain}: padj={float(row['adjusted_p_value']):.2e}, hits={row['foreground_hits']}")

# Find intersection for DOWN direction
print("\n\n=== DOWN DIRECTION INTERSECTION ===")
down_sets = {}
for strain in ['97', '98', '99']:
    key = f'{strain}_down'
    ds_id = results[key]
    header, data = parse_ora_results(ds_id)
    sig = set()
    for row in data:
        try:
            if float(row['adjusted_p_value']) < 0.05:
                sig.add(row['pathway_id'])
        except (ValueError, KeyError):
            pass
    down_sets[strain] = sig
    print(f"{key} significant: {sorted(sig)}")

down_common = down_sets['97'] & down_sets['98'] & down_sets['99']
print(f"\nCommon DOWN pathways: {sorted(down_common) if down_common else 'NONE'}")

# For the common ones, show details
if down_common:
    for pid in sorted(down_common):
        print(f"\n  {pid}:")
        for strain in ['97', '98', '99']:
            key = f'{strain}_down'
            ds_id = results[key]
            header, data = parse_ora_results(ds_id)
            for row in data:
                if row['pathway_id'] == pid:
                    print(f"    {strain}: padj={float(row['adjusted_p_value']):.2e}, hits={row['foreground_hits']}")

total = len(up_common) + len(down_common)
print(f"\n\n=== TOTAL common pathways (same direction across all 3 strains): {total} ===")
print(f"  UP: {len(up_common)}")
print(f"  DOWN: {len(down_common)}")
PYEOF

